  "Не выдумывает нормативы обслуживания, адреса, время прибытия, контакты или задержки.": "Does not invent service standards, addresses, arrival times, contacts or delays.",
  "Не включает продажу алкоголя.": "Does not enable alcohol sales.",
  "Эти действия нельзя выполнять по совету ИИ без защищённого серверного контроля.": "These actions must not run on AI advice without secure server-side controls.",
  "Назначенные активные доставки, время событий, утверждённые нормативы, подтверждение администратора, журнал действий и уведомления.": "Assigned active deliveries, event timestamps, approved standards, administrator approval, audit logs and notifications.",
  "Защищённая выборка завершённых доставок текущего курьера.": "A protected query for the current courier's completed deliveries.",
  "Серверная проверка личности текущего курьера.": "Server-side verification of the signed-in courier.",
  "Подтверждённые даты и время начала и завершения.": "Verified start and completion timestamps.",
  "Отдельный финансовый журнал для доходов и выплат.": "A separate financial ledger for earnings and payouts.",
  "До подключения истории на сервере показатели не рассчитываются по демонстрационным или чужим заказам.": "Until the history backend is connected, figures are not calculated from demo or other users' orders.",
  "Показатели за день, неделю и месяц без подтверждённого времени операций.": "Day, week and month totals without verified transaction times.",
  "Доход курьера без финансового журнала.": "Courier earnings without a financial ledger.",
  "Контакты и маршрут клиента без разрешённого доступа.": "Customer contacts and routes without approved access.",
  "Профиль пока недоступен для просмотра и изменения: необходимы защищённая загрузка данных курьера, проверка прав, серверное сохранение и журнал действий.": "Courier profile viewing and editing are disabled until secure reads, access checks, server-side updates and audit logging are connected.",
  "Рабочий режим должен загружать только профиль текущего курьера.": "Live mode must load only the signed-in courier's profile.",
  "Имя и контакты — только из подтверждённого профиля.": "Name and contact details must come from the verified profile.",
  "Документы и статус проверки обрабатываются отдельно в защищённом разделе.": "Documents and verification status are handled in a separate protected area.",
  "Доступ к геолокации предоставляется только с отдельного согласия.": "Location access requires separate explicit consent.",
  "Нет фиктивного сохранения, настроек смен или уведомлений.": "No fake save, shift settings or notification toggles.",
  "Любое изменение должно проверять права текущего курьера.": "Every update must verify the current courier's permissions.",
  "Секретные данные не изменяются через общий клиентский интерфейс.": "Sensitive data cannot be changed through the general customer interface.",
  "Для важных изменений обязателен журнал действий.": "Important changes must be recorded in an audit log.",
  "Данные получены из рабочей базы, а не из демонстрационных записей.": "Data comes from the live database, not from demo records.",
  "Демонстрационный режим показывает доставки без изменения реальных данных.": "Demo mode shows deliveries without changing live data.",
  "Доступ только для главного администратора.": "Chief administrator access only.",
  "Одобрение и публикация — отдельные решения главного администратора. Партнёр должен подтвердить цену и описание номера. Без подтверждённых свободных мест бронирование невозможно.": "Approval and publishing require separate chief administrator decisions. Partners must confirm room prices and details. Rooms cannot be booked without verified availability.",
  "База данных временно недоступна.": "Database temporarily unavailable.",
  "Назначение курьера выполняется защищённой серверной операцией после проверки прав. Интерфейс не изменяет данные доставки напрямую.": "Couriers are assigned through a secure server action after permission checks. The interface cannot change delivery records directly.",
  "Сейчас нет курьеров со статусом «На связи». Назначение станет доступно, когда появится свободный курьер.": "No couriers are currently online. Assignment will be available when an active courier becomes available.",
  "Реальные проблемы доставок с серверной проверкой прав администратора.": "Real delivery issues with server-side administrator permission checks.",
  "Данные получены из рабочей базы, без вымышленных сумм. Предварительная комиссия не считается фактической выручкой KÖL.": "Figures come from the live database without invented amounts. Estimated commission is not recognised KÖL revenue.",
  "Условия включения финансовых операций": "Requirements for enabling finance operations",
