  "Ссылка на документ и подтверждение собственника обязательны.": "A document reference and owner approval are required.",
  "Доступ разрешён только владельцу платформы.": "Only the platform owner has access.",
  "Поиск по электронной почте": "Search by email",
  "Поиск пользователя по электронной почте": "Find a user by email",
  "Показываются только записи из рабочей базы, не более 50 за один запрос.": "Only live database records are shown, up to 50 per search.",
  "База данных недоступна или права пользователя не подтверждены.": "The database is unavailable or permissions could not be verified.",
  "Этот экран предназначен только для просмотра. Заказы, оплаты и доставки изменяются через защищённые серверные операции с проверкой роли.": "This screen is view-only. Orders, payments and deliveries can only be changed through authorised server-side operations.",
  "Жалобы на пользователей, отзывы и сообщения о нарушениях пока не объединены в одну очередь.": "User complaints, reviews and abuse reports are not yet combined in one moderation queue.",
  "Здесь показаны только реальные обращения и переписка из рабочей базы. Ответы и статусы сохраняются защищённой серверной операцией.": "Only real support tickets and messages from the live database are shown. Replies and statuses use a secure server operation.",
  "Не более 100 последних обращений. Изменять их могут только администраторы поддержки и главный администратор; остальные имеют доступ только для просмотра.": "Up to 100 recent support tickets. Only support and chief administrators can make changes; other administrators have view-only access.",
