  "Демонстрационный режим": "Demo mode",
  "Создание, изменение и отправка блюд на проверку доступны только после подтверждения доступа к бизнесу. Без проверки прав изменения блокируются.": "Food items can be created, edited and submitted for review only after business access is verified. Changes without valid permissions are blocked.",
  "Создание, изменение и отправка туров на проверку доступны только после подтверждения доступа к бизнесу. Без проверки прав изменения блокируются.": "Tours can be created, edited and submitted for review only after business access is verified. Changes without valid permissions are blocked.",
  "Создание, изменение и отправка товаров на проверку доступны только после подтверждения доступа к бизнесу. Без проверки прав изменения блокируются.": "Products can be created, edited and submitted for review only after business access is verified. Changes without valid permissions are blocked.",
  "Создание, изменение и отправка жилья на проверку доступны только после подтверждения доступа к бизнесу. Без проверки прав изменения блокируются.": "Accommodation listings can be created, edited and submitted for review only after business access is verified. Changes without valid permissions are blocked.",
