  "KÖL · Управление доставкой": "KÖL · Delivery management",
  "Главный администратор управляет каталогом жилья: публикует одобренные объекты, снимает их с публикации или архивирует через защищённые серверные операции.": "The chief administrator manages accommodation listings, publishing approved properties, unpublishing them or archiving them through secure server actions.",
  "Главный администратор управляет каталогом туров: публикует одобренные предложения, снимает их с публикации или архивирует через защищённые серверные операции.": "The chief administrator manages tour listings, publishing approved offers, unpublishing them or archiving them through secure server actions.",
  "Главный администратор управляет каталогом блюд: публикует одобренные позиции, снимает их с публикации или архивирует через защищённые серверные операции.": "The chief administrator manages food listings, publishing approved items, unpublishing them or archiving them through secure server actions.",
  "Каталог товаров защищён проверками безопасности. Публикация товаров с предупреждениями или признаками алкогольной продукции блокируется в интерфейсе и базе данных.": "The products catalogue has safety checks. Publishing flagged or alcohol-related items is blocked in both the interface and database.",
