  "История не создаётся из общего списка заказов и не дополняется вымышленными временем, маршрутами или доходом.": "Delivery history is not built from the general order list or supplemented with invented times, routes or earnings.",
  "Сейчас защищённый источник показывает только активные назначения. Для завершённых доставок нужна отдельная история с проверкой прав курьера и завершённых статусов.": "The protected source currently shows only active assignments. Completed deliveries need separate history checks for courier permissions and final statuses.",
