  "Когда нужен админ": "When an administrator is needed",
  "Продажа и доставка алкоголя отключены. ИИ не может включить этот модуль. Для включения в будущем необходимы юридическая проверка, лицензирование, проверка партнёра и подтверждение главного администратора.": "Alcohol sales and delivery are disabled. AI cannot enable this module. Future activation requires legal review, licensing, partner verification and chief administrator approval.",
  "Изменения доступности номеров и туров выполняются через защищённую серверную операцию с проверкой роли, принадлежности бизнеса и журналом действий.": "Changes to room and tour availability use secure server operations with role, business ownership and audit checks.",
  "Изменения еды и товаров будут подключены отдельно. Сейчас эти элементы не изменяют записи в рабочей базе.": "Food and product changes will be enabled separately. These controls currently do not modify live database records.",
  "Принятые заказы и бронирования защищены. Отмена, оплата и возвраты требуют отдельных утверждённых правил.": "Accepted orders and bookings are protected. Cancellations, payments and refunds require separate approved rules.",
  "Изменение доступности влияет только на новые заявки. Принятые заказы и подтверждённые брони не отменяются.": "Availability changes affect only new requests. Accepted orders and confirmed bookings are not cancelled.",
  "`ALCOHOL_MODULE_ENABLED=false`. Возможное включение требует правовой проверки, лицензии, проверки партнёра и подтверждения главного администратора.": "`ALCOHOL_MODULE_ENABLED=false`. Any activation requires legal review, licensing, partner verification and chief administrator approval.",
  "Остановка влияет только на новые продажи и бронирования. Принятые обязательства защищены; отмену согласовывает администратор.": "Pausing affects only new sales and bookings. Accepted commitments are protected; cancellations require administrator approval.",
  "Отмена, оплата, возвраты, правовые вопросы и запросы, связанные с алкоголем, требуют проверки администратора.": "Cancellation, payment, refunds, legal matters and alcohol-related requests require administrator review.",
  "ИИ может рекомендовать остановку и готовить сообщения, но не выполняет опасные действия с каталогом.": "AI may recommend pauses and draft messages but cannot perform high-risk catalogue actions.",
  "Продажа алкоголя отключена. Остановка позиций каталога не может разрешить продажу или доставку алкоголя.": "Alcohol sales are disabled. Catalogue pause controls cannot enable alcohol sales or delivery.",
  "ИИ не может включить продажу алкоголя. Для возможного включения требуются правовая проверка, лицензия, проверка партнёра и одобрение главного администратора.": "AI cannot enable alcohol sales. Future activation requires legal review, licensing, partner verification and chief administrator approval.",
  "Демонстрационный режим: стоп-кнопка управляет новыми заказами и бронированиями, но не отменяет принятые обязательства.": "Demo mode: the pause control affects new orders and bookings but does not cancel existing commitments.",
  "Партнёр выбирает раздел, причину и время возобновления. Сохранение изменений здесь пока недоступно.": "The partner selects a section, reason and resumption time. Saving changes is not available here yet.",
  "Для этих ситуаций необходимы подтверждение администратора, обоснование и запись в журнал действий.": "These cases require administrator approval, justification and audit logging.",
  "ИИ-диспетчер помогает обнаружить перегрузку и подготовить сообщение, но не выполняет опасные действия.": "The AI dispatcher helps detect overload and draft messages but does not execute high-risk actions.",
  "Продажа алкоголя отключена. Связанные с алкоголем запросы требуют правовой проверки, лицензии, проверки партнёра и одобрения главного администратора.": "Alcohol sales are disabled. Alcohol-related requests require legal review, licensing, partner verification and chief administrator approval.",
  "ИИ не может включить продажу алкоголя. Остановка продаж не разрешает операции с алкоголем и не обходит ограничения.": "AI cannot enable alcohol sales. Pausing sales does not authorise alcohol operations or bypass restrictions.",
