  "Wikimedia Commons изображения могут отображаться в адаптивном интерфейсе с техническим масштабированием или кадрированием. Ссылки ниже ведут на оригинальные страницы файлов и соответствующие лицензии.": "Wikimedia Commons images may be resized or cropped for responsive layouts. Links below lead to original file pages and licenses.",
