  "Загрузите изображение JPG, PNG или WebP размером до 4 МБ. Фон применяется к главной странице под контентом; утверждённая анимация остаётся. Баннер размещается после поиска. Загрузка сохраняет черновик, а сайт изменится только после публикации.": "Upload a JPG, PNG or WebP image up to 4 MB. The background appears behind homepage content; the approved animation remains. The banner appears below search. Uploading saves a draft; the live site changes only after publishing.",
