  "Баннер сайта": "Site banner",
  "Баннер KÖL": "KÖL banner",
  "Только SUPER ADMIN может приглашать сотрудников и менять разрешённые роли. Клиенты регистрируются самостоятельно. Все изменения записываются в журнал. Перевод между типами кабинетов и создание ещё одного SUPER ADMIN требуют отдельной защищённой процедуры.": "Only SUPER ADMIN can invite staff and change permitted roles. Clients register themselves. Every change is logged. Switching between account types or creating another SUPER ADMIN requires a separate secure process.",
