  "Передача проблемы администратору станет доступна после подключения защищённой серверной обработки обращений.": "Көйгөйдү администраторго өткөрүү корголгон сервердик кайрылуу кызматы туташкандан кийин жеткиликтүү болот.",
  "Обращение может относиться только к доставке, назначенной текущему курьеру.": "Кайрылуу учурдагы курьерге дайындалган жеткирүүгө гана тиешелүү болушу мүмкүн.",
  "Нельзя раскрывать или изменять доставку, не назначенную текущему курьеру.": "Учурдагы курьерге дайындалбаган жеткирүүнү көрүүгө же өзгөртүүгө болбойт.",
  "Проблема активной доставки должна сохраняться защищённой серверной операцией с записью в журнал.": "Активдүү жеткирүүдөгү көйгөй корголгон сервердик аракет менен журналга жазылышы керек.",
  "Форма обращения недоступна до подключения проверки назначения курьера и журнала действий.": "Курьердин дайындоосун текшерүү жана аракеттер журналы иштемейинче кайрылуу формасы өчүк болот.",
  "ИИ может только рекомендовать передачу проблемы администратору на основе подтверждённых данных.": "AI ырасталган маалыматтардын негизинде көйгөйдү администраторго өткөрүүнү гана сунуштай алат.",
  "Проблемы с профилем обрабатываются только после подтверждения учётной записи курьера и обращения в поддержку.": "Профиль көйгөйлөрү курьердин аккаунту ырасталгандан кийин колдоо кызматы аркылуу чечилет.",
