  "Главный администратор управляет каталогом жилья: публикует одобренные объекты, снимает их с публикации или архивирует через защищённые серверные операции.": "Башкы администратор турак жай каталогун башкарат: бекитилген объекттерди жарыялайт, жарыядан алып салат же корголгон сервердик аракеттер менен архивдейт.",
  "Главный администратор управляет каталогом туров: публикует одобренные предложения, снимает их с публикации или архивирует через защищённые серверные операции.": "Башкы администратор турлар каталогун башкарат: бекитилген сунуштарды жарыялайт, жарыядан алып салат же корголгон сервердик аракеттер менен архивдейт.",
  "Главный администратор управляет каталогом блюд: публикует одобренные позиции, снимает их с публикации или архивирует через защищённые серверные операции.": "Башкы администратор тамактар каталогун башкарат: бекитилген позицияларды жарыялайт, жарыядан алып салат же корголгон сервердик аракеттер менен архивдейт.",
  "Каталог товаров защищён проверками безопасности. Публикация товаров с предупреждениями или признаками алкогольной продукции блокируется в интерфейсе и базе данных.": "Товарлар каталогу коопсуздук текшерүүлөрү менен корголгон. Эскертүү коюлган же алкоголго байланышкан товарларды жарыялоо интерфейсте да, маалымат базасында да бөгөттөлөт.",
