  "История не создаётся из общего списка заказов и не дополняется вымышленными временем, маршрутами или доходом.": "Жеткирүү тарыхы заказдардын жалпы тизмесинен түзүлбөйт жана ойдон чыгарылган убакыт, каттам же киреше менен толукталбайт.",
  "Сейчас защищённый источник показывает только активные назначения. Для завершённых доставок нужна отдельная история с проверкой прав курьера и завершённых статусов.": "Азыр корголгон булак активдүү дайындоолорду гана көрсөтөт. Аяктаган жеткирүүлөр үчүн курьердин укуктарын жана акыркы абалдарды текшерген өзүнчө тарых керек.",
