  "Блюда загружаются только из каталога вашего бизнеса. Часы работы и доступность не заменяются вымышленным расписанием.": "Тамактар бизнесиңиздин каталогунан гана жүктөлөт. Иш убактысы жана жеткиликтүүлүк ойдон чыгарылган жадыбал менен алмаштырылбайт.",
