  "Дизайн-система туристической платформы Иссык-Куля: туры, жильё, еда, магазин, бронирование и кабинеты партнёров.": "Ысык-Көлдүн туристтик платформасынын дизайн тутуму: турлар, турак жай, тамак-аш, дүкөн, брондоолор жана өнөктөш кабинеттер.",
