  "Эта страница не подтверждает создание заказа без проверенного ответа серверной транзакции.": "Бул барак сервердик транзакция ырасталмайынча заказ түзүлгөнүн ырастабайт.",
  "Это необязательно: заявку можно отправить и без кабинета.": "Милдеттүү эмес: өтүнмөнү аккаунтсуз да жөнөтсөңүз болот.",
  "Профиль не показывает вымышленные имя, телефон, транспорт, номер машины, смену или настройки уведомлений.": "Профиль ойдон чыгарылган ысымдарды, телефондорду, транспортту, унаа номерлерин, нөөмөттөрдү же билдирүү жөндөөлөрүн көрсөтпөйт.",
  "Вернуться на публичную витрину KÖL": "KÖLдүн жалпы барагына кайтуу",
  "Демонстрационный главный блок будущих публичных страниц без каталога и серверных операций.": "Келечектеги коомдук барактар үчүн үлгү башкы бөлүк, каталогсуз жана сервердик операцияларсыз.",
  "Оставьте обращение: оно сохранится в системе заявок KÖL. Контактные каналы публикуются только после подтверждения владельцем.": "Кайрылууңузду жөнөтүңүз: ал KÖL өтүнмөлөр тутумуна сакталат. Байланыш каналдары ээси ырастагандан кийин гана жарыяланат.",
  "Просмотр заказа не меняет его статус, оплату или итоговые суммы.": "Заказды көрүү анын абалын, төлөмүн же жалпы суммасын өзгөртпөйт.",
