  "опасные действия требуют подтверждения человека": "кооптуу аракеттер адамдын ырастоосун талап кылат",
  "Статусы заказов изменяются только через подтверждённую серверную транзакцию с проверкой роли и записью в журнал действий.": "Буйрутмалардын абалы ролду текшерүү жана аракеттер журналына жазуу менен ырасталган сервердик транзакция аркылуу гана өзгөрөт.",
  "Проблема записана в журнал действий без изменения подтверждённых данных заказа и оплаты.": "Көйгөй буйрутманын жана төлөмдүн ырасталган маалыматтарын өзгөртпөстөн аракеттер журналына катталды.",
