  "Последние заказы еды и товаров текущего бизнеса.": "Бул ишкананын акыркы тамак-аш жана товар буйрутмалары.",
  "Бронирования жилья и туров текущего бизнеса.": "Бул ишкананын турак жай жана тур брондоолору.",
  "KÖL — Иссык-Куль / Ысык-Көл · Платформа путешествий": "KÖL — Ысык-Көл · Саякат платформасы",
  "Оформление сайта: фон и баннер": "Сайттын жасалгасы: фон жана баннер",
  "Загрузите изображение JPG, PNG или WebP размером до 4 МБ. Фон применяется к главной странице под контентом; утверждённая анимация остаётся. Баннер размещается после поиска. Загрузка сохраняет черновик, а сайт изменится только после публикации.": "4 МБга чейинки JPG, PNG же WebP сүрөтүн жүктөңүз. Фон башкы беттеги мазмундун артында көрсөтүлөт; бекитилген анимация сакталат. Баннер издөөдөн кийин жайгашат. Жүктөлгөн сүрөт адегенде каралама болуп сакталат; сайт жарыялангандан кийин гана өзгөрөт.",
