  "Приглашение принято. Установите пароль ниже, чтобы затем входить в рабочий кабинет по email и паролю.": "Чакыруу кабыл алынды. Иш кабинетиңизге электрондук почта жана сырсөз аркылуу кирүү үчүн төмөндө сырсөз орнотуңуз.",
  "Партнёрская организация (только для партнёрских ролей)": "Өнөктөш уюм (өнөктөш ролдору үчүн гана)",
