  "Рабочий финансовый источник истины ещё не подключён для банковской сверки и фактических выплат. Договоры, начисленные расходы и признанные комиссии учитываются в финансовом журнале.": "Банктык салыштыруу жана иш жүзүндөгү төлөмдөр үчүн текшерилген каржы тутуму али туташкан эмес. Келишимдер, эсептелген чыгымдар жана таанылган комиссиялар каржы журналында эсепке алынат.",
  "Финансовый результат по учтённым операциям": "Эсепке алынган операциялар боюнча каржылык натыйжа",
  "Текущий месяц · отдельно по каждой валюте": "Учурдагы ай · ар бир валюта боюнча өзүнчө",
