  "Результат по проведённым записям": "Журналга киргизилген жазуулар боюнча натыйжа",
  "За период нет признанных доходов и начисленных расходов.": "Бул мезгилде таанылган киреше жана эсептелген чыгымдар жок.",
  "Финансовая сводка недоступна.": "Каржылык жыйынтык жеткиликсиз.",
  "Разница признанных комиссий и начисленных расходов не является чистой прибылью: налоги, полнота затрат и банковские расчёты учитываются отдельно.": "Таанылган комиссиялар менен эсептелген чыгымдардын айырмасы таза пайда эмес: салыктар, чыгымдардын толуктугу жана банктык эсептешүүлөр өзүнчө эсепке алынат.",
