  "Договорные комиссии партнёров": "Өнөктөштөрдүн келишимдик комиссиялары",
  "Условия утверждаются собственником по договору. Ставки не назначаются автоматически.": "Шарттарды ээси келишимдин негизинде бекитет. Тарифтер автоматтык түрдө коюлбайт.",
